1	// The site publishes the canon ref this repo is vendored at, but it reads it
2	// from site/data/promoted.js while the authoritative value lives in
3	// .claudinite-checks.json (`claudinite.ref`) — two files that can't share an
4	// import (a JSON manifest and a plain browser script). Baselining bumps the
5	// manifest on its own schedule and auto-merges, and nothing in that path ever
6	// touches the site data, so the two copies drift apart by default and the page
7	// keeps advertising a ref the repo has already left behind.
8	//
9	// Dependency-free by the local-pack contract: plain finding objects, no import
10	// of the vendored engine's helpers.
11	const CONFIG = '.claudinite-checks.json';
12	const PROMOTED = 'site/data/promoted.js';
13	const CANON_REF = /canonRef\s*:\s*'([0-9a-f]+)'/;
14	
15	const lineOf = (text, index) => text.slice(0, index).split('\n').length;
16	
17	const rule = {
18	  id: 'site/canon-ref-in-step',
19	  severity: 'blocking',
20	  description: "site/data/promoted.js's canonRef must be the short form of the vendored ref in .claudinite-checks.json",
21	  doc: 'site/README.md',
22	  why: 'the site states the canon ref as a verifiable fact, and baselining bumps the declaration without ever touching the site data — left unguarded the copies only drift apart',
23	
24	  run(ctx) {
25	    const promoted = ctx.read(PROMOTED);
26	    const config = ctx.read(CONFIG);
27	    if (promoted === null || config === null) return [];
28	
29	    let ref;
30	    try {
31	      ref = JSON.parse(config)?.claudinite?.ref;
32	    } catch {
33	      return []; // malformed settings is the world runner's own finding, not this rule's
34	    }
35	    if (typeof ref !== 'string' || !ref) return [];
36	
37	    const match = CANON_REF.exec(promoted);
38	    if (!match) {
39	      return [{
40	        rule: rule.id,
41	        severity: rule.severity,
42	        file: PROMOTED,
43	        line: null,
44	        what: 'no canonRef literal — the site has no ref to show and nothing pins it to the vendored canon',
45	        why: rule.why,
46	        fix: `add \`canonRef: '${ref.slice(0, 7)}',\` to the exported object`,
47	        doc: rule.doc,
48	      }];
49	    }
50	
51	    const short = match[1];
52	    if (ref.startsWith(short)) return [];
53	
54	    return [{
55	      rule: rule.id,
56	      severity: rule.severity,
57	      file: PROMOTED,
58	      line: lineOf(promoted, match.index),
59	      what: `canonRef is '${short}' but ${CONFIG} is vendored at ${ref}`,
60	      why: rule.why,
61	      fix: `set canonRef to '${ref.slice(0, short.length)}' — whatever moves the vendored ref (baselining included) must move the site's copy in the same change`,
62	      doc: rule.doc,
63	    }];
64	  },
65	};
66	
67	export default rule;
68

1	// Red-first fixtures for this pack's checks. Dependency-free, node:test only:
2	//   node --test .claudinite/local/packs/claudinite-website/pack.test.mjs
3	import test from 'node:test';
4	import assert from 'node:assert/strict';
5	
6	import canonRefInStep from './canon-ref-in-step.mjs';
7	
8	// Minimal stand-in for the engine's context: rules only ever call ctx.read().
9	const ctx = (files) => ({ read: (path) => (path in files ? files[path] : null) });
10	
11	const config = (ref) => JSON.stringify({ packs: ['basics'], claudinite: { ref } });
12	const promoted = (short) => `window.CLAUDINITE = {\n  canonRepo: 'x',\n  canonRef: '${short}',\n};\n`;
13	
14	const SHA = '005edd2028b770facd2be74812b29556ced5194d';
15	
16	test('canon-ref-in-step: green when the site short ref prefixes the vendored ref', () => {
17	  const found = canonRefInStep.run(ctx({
18	    '.claudinite-checks.json': config(SHA),
19	    'site/data/promoted.js': promoted('005edd2'),
20	  }));
21	  assert.deepEqual(found, []);
22	});
23	
24	test('canon-ref-in-step: red when baselining moved the vendored ref and the site kept the old one', () => {
25	  const found = canonRefInStep.run(ctx({
26	    '.claudinite-checks.json': config('8b31f77aa1c0de4455e2c93a7ba0f6d0d1e2f3a4'),
27	    'site/data/promoted.js': promoted('005edd2'),
28	  }));
29	  assert.equal(found.length, 1);
30	  assert.equal(found[0].file, 'site/data/promoted.js');
31	  assert.equal(found[0].line, 3);
32	  assert.match(found[0].fix, /8b31f77/);
33	});
34	
35	test('canon-ref-in-step: red when the site data carries no canonRef at all', () => {
36	  const found = canonRefInStep.run(ctx({
37	    '.claudinite-checks.json': config(SHA),
38	    'site/data/promoted.js': "window.CLAUDINITE = {\n  canonRepo: 'x',\n};\n",
39	  }));
40	  assert.equal(found.length, 1);
41	  assert.match(found[0].fix, /005edd2/);
42	});
43	
44	test('canon-ref-in-step: inert when either file is absent or the settings are malformed', () => {
45	  assert.deepEqual(canonRefInStep.run(ctx({ '.claudinite-checks.json': config(SHA) })), []);
46	  assert.deepEqual(canonRefInStep.run(ctx({ 'site/data/promoted.js': promoted('005edd2') })), []);
47	  assert.deepEqual(canonRefInStep.run(ctx({
48	    '.claudinite-checks.json': '{ not json',
49	    'site/data/promoted.js': promoted('005edd2'),
50	  })), []);
51	});
