174	  // of the prior capture then dies mid-read (ENOBUFS) and a long session can
175	  // never append its delta.
176	  const r = spawnSync('git', args, { cwd: root, encoding: 'utf8', input, maxBuffer: 256 * 1024 * 1024 });
