211	// session captured first) recomputes against the fresh tip instead of clobbering.
212	export async function capture({ root, branch, sessionId, bundled, issue, now, redactions = [] }) {
213	  for (let attempt = 1; attempt <= 3; attempt += 1) {
214	    const tip = fetchTip(root, branch);
215	    const treeLines = tip
216	      ? git(root, ['ls-tree', tip]).stdout.split('\n').filter(Boolean)
217	      : [];
218	    const names = treeLines.map((l) => l.split('\t')[1]);
219	
220	    const prior = names.filter((n) => n.endsWith(`--${sessionId}.jsonl`));
