283	// survives the case the slug cannot: a remote/web session whose launch cwd (and
284	// thus transcript slug) differs from the git-root path this script derives, which
285	// otherwise points at a directory that never existed. Fall back to the slug
286	// directory's newest transcript, then to the newest transcript anywhere.
287	export function findTranscript({ root, sessionId, projects = projectsRoot() }) {
